package com.citacloud.app.models;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="detalle_orden_estudio") public class DetalleOrdenEstudio {@Id @GeneratedValue private UUID id; @Column(name="orden_id") private UUID ordenId; private String tipo,estudio,estado; @Column(name="fecha_resultado") private LocalDate fechaResultado; @Column(columnDefinition="TEXT") private String resultado; @Column(name="observaciones_resultado",columnDefinition="TEXT") private String observacionesResultado; @Column(name="centro_realizador") private String centroRealizador; @Column(name="archivo_url") private String archivoUrl; @Column(name="registrado_por") private UUID registradoPor; @Column(name="creado_en") private LocalDateTime creadoEn; @Column(name="actualizado_en") private LocalDateTime actualizadoEn; public UUID getId(){return id;} public UUID getOrdenId(){return ordenId;} public String getTipo(){return tipo;} public String getEstudio(){return estudio;} public String getEstado(){return estado;} public LocalDate getFechaResultado(){return fechaResultado;} public String getResultado(){return resultado;} public String getObservacionesResultado(){return observacionesResultado;} public String getCentroRealizador(){return centroRealizador;} public String getArchivoUrl(){return archivoUrl;} public void setOrdenId(UUID v){ordenId=v;} public void setTipo(String v){tipo=v;} public void setEstudio(String v){estudio=v;} public void setEstado(String v){estado=v;} public void setFechaResultado(LocalDate v){fechaResultado=v;} public void setResultado(String v){resultado=v;} public void setObservacionesResultado(String v){observacionesResultado=v;} public void setCentroRealizador(String v){centroRealizador=v;} public void setArchivoUrl(String v){archivoUrl=v;} public void setRegistradoPor(UUID v){registradoPor=v;} public void setCreadoEn(LocalDateTime v){creadoEn=v;} public void setActualizadoEn(LocalDateTime v){actualizadoEn=v;} }
